svg.script:
(function() {
  var n = 255;
  var baseInterval = 30;
  var speed = 1.35; // leve aceleracao em relacao ao gif original
  var current = 0;
  var images = [];
  for (var i = 0; i < n; i++) {
    images.push(document.getElementById('f' + i));
  }
  function tick() {
    var next = (current + 1) % n;
    images[current].setAttribute('opacity', '0');
    images[next].setAttribute('opacity', '1');
    current = next;
  }
  setInterval(tick, baseInterval / speed);
})();
